<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/shop_checkout.php';
if(!isset($_SESSION['trener_id'])||!roleAtLeast('admin')){header('Location: login.php');exit;}
function packetaAdminH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
    if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new InvalidArgumentException('Formulář vypršel. Obnovte stránku.');
    $price=(string)($_POST['price']??'');if(!preg_match('/^\d{1,5}(?:[,.]\d{1,2})?$/D',$price))throw new InvalidArgumentException('Zadejte cenu dopravy v Kč.');
    $parts=explode('.',str_replace(',','.',$price),2);$minor=(int)$parts[0]*100+(int)str_pad($parts[1]??'0',2,'0');
    shopPacketaSaveSettings($pdo,(int)$_SESSION['trener_id'],$minor,(string)($_POST['widget_api_key']??''),($_POST['enabled']??'')==='1',(string)($_POST['reason']??''),($_POST['confirmed']??'')==='1');
    header('Location: eshop_packeta_admin.php?saved=1',true,303);exit;
}catch(InvalidArgumentException|ShopPacketaException $e){$errors[]=$e->getMessage();}catch(PDOException $e){error_log('eshop_packeta_admin: '.get_class($e));$errors[]='Nastavení se nepodařilo uložit.';}
$settings=shopPacketaSettings($pdo);$ready=shopPacketaAvailable(['enabled'=>true,'price_minor'=>max(1,$settings['price_minor']),'widget_api_key'=>$settings['widget_api_key']]);
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doručení Zásilkovnou</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?><main class="container py-4" style="max-width:900px"><a href="eshop_orders_admin.php" class="btn btn-sm btn-outline-secondary mb-3">← Objednávky</a><h1 class="h3">Doručení Zásilkovnou do Z-BOXu</h1>
<?php foreach($errors as $e):?><div class="alert alert-danger"><?=packetaAdminH($e)?></div><?php endforeach;?><?php if(($_GET['saved']??'')==='1'):?><div class="alert alert-success">Nastavení bylo uloženo a auditováno.</div><?php endif;?>
<?php if(shopPacketaLocalDemoEnabled()):?><div class="alert alert-warning">LOCALHOST TEST: aktivní je pouze syntetický Z-BOX. Veřejný klíč není potřeba; aplikace nevolá Zásilkovnu. Štítek i fyzické podání při této zkoušce pouze simulujeme.</div><?php else:?><div class="alert alert-<?=$ready?'info':'warning'?>">Výběr boxů: <strong><?=$ready?'připraven podle konfigurace':'není kompletní'?></strong>. Zadejte veřejný 16znakový klíč widgetu, ne API heslo. Tato integrace zatím nevytváří štítky přes API; zásilka se založí ručně v Klientu Zásilkovny.</div><?php endif;?>
<form method="post" class="card card-body shadow-sm border-0"><?=csrf_field()?><div class="mb-3"><label class="form-label fw-semibold" for="packeta-price">Cena dopravy v Kč</label><input id="packeta-price" class="form-control" name="price" inputmode="decimal" required value="<?=packetaAdminH(number_format($settings['price_minor']/100,2,',',''))?>"><div class="form-text">Jedna cena za objednávku; zahrne se do platby.</div></div><div class="mb-3"><label class="form-label fw-semibold" for="packeta-key">Veřejný klíč widgetu</label><input id="packeta-key" class="form-control" name="widget_api_key" maxlength="64" value="<?=packetaAdminH($settings['widget_api_key'])?>"></div><div class="form-check mb-3"><input id="packeta-enabled" class="form-check-input" type="checkbox" name="enabled" value="1" <?=$settings['enabled']?'checked':''?>><label for="packeta-enabled" class="form-check-label">Nabízet Zásilkovnu Z-BOX zákazníkům</label></div><div class="mb-3"><label class="form-label fw-semibold" for="packeta-reason">Důvod změny</label><input id="packeta-reason" class="form-control" name="reason" minlength="5" maxlength="1000" required></div><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="confirmed" value="1" required><span class="form-check-label">Potvrzuji změnu nabídky a ceny dopravy.</span></label><button class="btn btn-success">Uložit nastavení</button></form>
<div class="card card-body border-0 shadow-sm mt-3 small"><strong>Postup odeslání</strong><ol class="mb-0 mt-2"><li>Po zaplacení objednávku zabalte a označte jako připravenou.</li><li>V Klientu Zásilkovny vytvořte zásilku, vytiskněte štítek a v administraci uložte čárový kód i devítimístný podací kód.</li><li>Vložte balík do Z-BOXu, zadejte podací kód a fyzicky zavřete schránku.</li><li>Teprve potom potvrďte podání v administraci. Zákazník dostane sledovací číslo; interní podací kód se smaže.</li></ol></div></main></body></html>
